sp_widget.client_script:
/* ==========================================================================
 * EDP Hero + Carousel — client script
 * ==========================================================================
 * Controller alias is `c` (var c = this). No $scope manipulation beyond the
 * documented lifecycle hooks.
 *
 * Carousel behaviour:
 *   c.index            current slide
 *   c.playing          auto-rotation running
 *   c.autoplayAllowed  false when prefers-reduced-motion: reduce, or when
 *                      the `autoplay` option is off, or with <2 slides
 *   c.politeness       'off' while rotating, 'polite' once the user drives it
 *   c.direction        'is-next' / 'is-prev' — set on the VIEWPORT and used
 *                      only to pick which side the incoming slide enters
 *                      from. Purely cosmetic, and disabled under reduced
 *                      motion.
 *
 * Rendering note: all slides stay mounted (see template.html). Changing
 * `c.index` only moves the `.is-active` class, so there is never a moment
 * where two slides are painted at once.
 *
 * The prev/next arrow buttons were removed from the template. `c.prev()` and
 * `c.next()` are kept because ArrowLeft / ArrowRight still call them — do not
 * delete them or keyboard navigation breaks.
 * ========================================================================== */
api.controller = function ($scope, $element, $interval, $window, spUtil) {
    var c = this;

    var KEY_LEFT = 37;
    var KEY_RIGHT = 39;
    var KEY_HOME = 36;
    var KEY_END = 35;

    c.uid = spUtil && spUtil.generateUniqueID ? spUtil.generateUniqueID() : ('edp' + Date.now());
    c.slides = (c.data && c.data.slides) ? c.data.slides : [];
    c.index = 0;
    c.hovering = false;
    c.focused = false;
    c.direction = 'is-next';

    /* --- reduced motion: NEVER auto-advance ----------------------------- */
    c.reduceMotion = !!($window.matchMedia &&
        $window.matchMedia('(prefers-reduced-motion: reduce)').matches);

    c.autoplayAllowed = !!c.data.autoplay && !c.reduceMotion && c.slides.length > 1;
    c.playing = c.autoplayAllowed;
    c.politeness = c.playing ? 'off' : 'polite';

    var timer = null;

    function syncPoliteness() {
        // While the carousel rotates on its own it must NOT shout at screen
        // readers; once the user takes control, announce the new slide.
        c.politeness = (c.playing && !c.hovering && !c.focused) ? 'off' : 'polite';
    }

    function stopTimer() {
        if (timer) {
            $interval.cancel(timer);
            timer = null;
        }
    }

    function startTimer() {
        stopTimer();
        if (!c.playing || c.hovering || c.focused || !c.autoplayAllowed) {
            return;
        }
        timer = $interval(function () {
            c.direction = 'is-next';
            c.index = (c.index + 1) % c.slides.length;
        }, c.data.intervalMs);
    }

    function restart() {
        syncPoliteness();
        startTimer();
    }

    /* --- navigation ----------------------------------------------------- */
    c.goTo = function (i) {
        if (!c.slides.length) {
            return;
        }
        // Travel direction, for the CSS enter animation only (cosmetic).
        c.direction = (i < c.index) ? 'is-prev' : 'is-next';
        c.index = ((i % c.slides.length) + c.slides.length) % c.slides.length;
        c.politeness = 'polite';
        startTimer(); // reset the dwell time on the newly shown slide
    };

    c.next = function () {
        c.goTo(c.index + 1);
    };

    c.prev = function () {
        c.goTo(c.index - 1);
    };

    c.togglePlay = function () {
        c.playing = !c.playing;
        restart();
    };

    /* --- pause on hover / focus ----------------------------------------- */
    c.setHover = function (isHovering) {
        c.hovering = !!isHovering;
        restart();
    };

    c.setFocus = function (isFocused) {
        c.focused = !!isFocused;
        restart();
    };

    /* --- keyboard ------------------------------------------------------- */
    c.onKeydown = function ($event) {
        if (!$event) {
            return;
        }
        var code = $event.keyCode || $event.which;
        if (code === KEY_LEFT) {
            $event.preventDefault();
            c.prev();
        } else if (code === KEY_RIGHT) {
            $event.preventDefault();
            c.next();
        } else if (code === KEY_HOME) {
            $event.preventDefault();
            c.goTo(0);
        } else if (code === KEY_END) {
            $event.preventDefault();
            c.goTo(c.slides.length - 1);
        }
    };

    /* --- pause while keyboard focus is anywhere inside the carousel -----
     * `focus`/`blur` do not bubble, so ng-focus / ng-blur on the region only
     * fire for the region itself. focusin / focusout DO bubble, which is what
     * actually delivers "pause on focus" when the user tabs onto a dot or the
     * play button.
     * ------------------------------------------------------------------- */
    var region = $element[0].querySelector('.edp-carousel');

    function onFocusIn() {
        $scope.$applyAsync(function () {
            c.setFocus(true);
        });
    }

    function onFocusOut() {
        $scope.$applyAsync(function () {
            c.setFocus(false);
        });
    }

    if (region) {
        region.addEventListener('focusin', onFocusIn);
        region.addEventListener('focusout', onFocusOut);
    }

    /* --- lifecycle ------------------------------------------------------ */
    startTimer();

    // $scope is injected for the destroy hook and the focus digests only —
    // all data access stays on the `c` controller alias.
    $scope.$on('$destroy', function () {
        stopTimer();
        if (region) {
            region.removeEventListener('focusin', onFocusIn);
            region.removeEventListener('focusout', onFocusOut);
        }
    });
};

sp_widget.css:
/* ==========================================================================
 * EDP Hero + Carousel — styles
 * ==========================================================================
 * Premium feel, CSS only. No three.js / WebGL / external library of any kind.
 *   * CSS gradient-mesh ("aurora") background that DRIFTS IN ONCE and settles
 *   * animated inline-SVG line-art doodle, drawn with stroke-dashoffset, that
 *     settles to a static resting state after the draw-on completes
 *   * frosted-glass carousel pane with layered translucency + depth
 *   * single-visible, directional slide transition (never double-rendered)
 *   * tasteful micro-interactions on the CTA and carousel controls
 *
 * MOTION POLICY (important — this is what keeps the page reachable by
 * automated UI diagnostics and keeps it calm for users):
 *   * NOTHING animates forever in the steady state. Every entrance animation
 *     is finite (`both` / 1 iteration) and ends on a static frame, so the
 *     browser reaches an idle state shortly after load.
 *   * Ambient looping motion only resumes while the hero is HOVERED, and is
 *     disabled entirely under prefers-reduced-motion.
 *   * Under prefers-reduced-motion the doodle renders in its FINAL drawn
 *     state (stroke-dashoffset: 0) with no animation at all.
 * ========================================================================== */

/* ---------------- HERO SHELL ------------------------------------------ */
.edp-hero {
    position: relative;
    overflow: hidden;
    border-radius: var(--edp-radius-lg);
    padding: $sp-space-8 $sp-space-6;
    margin: $sp-space-5 0 $sp-space-6;
    background-color: var(--edp-surface);
    border: 1px solid var(--edp-hairline);
    box-shadow: var(--edp-shadow-2);
    isolation: isolate;
}

/* --- gradient mesh / aurora --- */
.edp-hero-aurora {
    position: absolute;
    inset: 0;
    z-index: -1;
    overflow: hidden;
    border-radius: inherit;
    background:
        radial-gradient(120% 90% at 100% 0%, var(--edp-aurora-4) 0%, transparent 60%),
        linear-gradient(135deg, var(--edp-bg) 0%, var(--edp-bg-elevated) 100%);
}

.edp-hero-blob {
    position: absolute;
    display: block;
    border-radius: 50%;
    filter: blur(60px);
    opacity: 0.9;
}

/* Each blob eases in from an offset position to its RESTING transform and
   then stops (`both` + single iteration). No `infinite` anywhere. */
.edp-hero-blob--1 {
    width: 46%;
    padding-bottom: 46%;
    top: -14%;
    left: -8%;
    background: var(--edp-aurora-1);
    animation: edp-settle-a 7s cubic-bezier(0.22, 0.61, 0.36, 1) both;
}

.edp-hero-blob--2 {
    width: 40%;
    padding-bottom: 40%;
    bottom: -18%;
    left: 28%;
    background: var(--edp-aurora-2);
    animation: edp-settle-b 8s cubic-bezier(0.22, 0.61, 0.36, 1) both;
}

.edp-hero-blob--3 {
    width: 38%;
    padding-bottom: 38%;
    top: 6%;
    right: -10%;
    background: var(--edp-aurora-3);
    animation: edp-settle-c 9s cubic-bezier(0.22, 0.61, 0.36, 1) both;
}

/* Ambient drift is OPT-IN: it only runs while the hero is hovered, so the
   steady state of the page stays completely static. */
.edp-hero:hover .edp-hero-blob--1 {
    animation: edp-drift-a 26s ease-in-out infinite alternate;
}

.edp-hero:hover .edp-hero-blob--2 {
    animation: edp-drift-b 32s ease-in-out infinite alternate;
}

.edp-hero:hover .edp-hero-blob--3 {
    animation: edp-drift-c 29s ease-in-out infinite alternate;
}

/* Very fine tonal veil so the blur gradients never look banded. */
.edp-hero-grain {
    position: absolute;
    inset: 0;
    display: block;
    background-image: repeating-linear-gradient(
        0deg,
        rgba(255, 255, 255, 0.015) 0px,
        rgba(255, 255, 255, 0.015) 1px,
        transparent 1px,
        transparent 3px
    );
    pointer-events: none;
}

/* One-shot settle keyframes: end frame == resting frame. */
@keyframes edp-settle-a {
    from { transform: translate3d(6%, 5%, 0) scale(1.06); }
    to   { transform: translate3d(0, 0, 0) scale(1); }
}

@keyframes edp-settle-b {
    from { transform: translate3d(-7%, -6%, 0) scale(0.95); }
    to   { transform: translate3d(0, 0, 0) scale(1); }
}

@keyframes edp-settle-c {
    from { transform: translate3d(-6%, 7%, 0) scale(1.07); }
    to   { transform: translate3d(0, 0, 0) scale(1); }
}

/* Hover-only ambient loops. */
@keyframes edp-drift-a {
    0%   { transform: translate3d(0, 0, 0) scale(1); }
    50%  { transform: translate3d(8%, 6%, 0) scale(1.08); }
    100% { transform: translate3d(-4%, 10%, 0) scale(0.96); }
}

@keyframes edp-drift-b {
    0%   { transform: translate3d(0, 0, 0) scale(1.04); }
    50%  { transform: translate3d(-10%, -8%, 0) scale(0.94); }
    100% { transform: translate3d(6%, -4%, 0) scale(1.1); }
}

@keyframes edp-drift-c {
    0%   { transform: translate3d(0, 0, 0) scale(0.98); }
    50%  { transform: translate3d(-8%, 10%, 0) scale(1.1); }
    100% { transform: translate3d(-2%, -6%, 0) scale(1); }
}

/* ---------------- ANIMATED DOODLE (decorative) ------------------------
 * Sits ABOVE the aurora (z-index 0 vs -1) and BELOW .edp-hero-inner
 * (z-index 1), so the two decorative layers compose instead of fighting and
 * nothing can cover an interactive element. Never focusable, never hit-tested.
 * -------------------------------------------------------------------- */
.edp-doodle {
    position: absolute;
    inset: 0;
    z-index: 0;
    overflow: hidden;
    border-radius: inherit;
    pointer-events: none;
}

.edp-doodle-svg {
    position: absolute;
    right: -1%;
    bottom: -3%;
    width: 46%;
    max-width: 460px;
    height: auto;
    opacity: 0.62;
    pointer-events: none;
}

/* Line work: loose hand-drawn feel — light weight, round caps, slight
   irregularity comes from the bezier control points in the markup. */
.edp-doodle-line {
    fill: none;
    stroke: var(--edp-accent);
    stroke-width: 1.6;
    stroke-linecap: round;
    stroke-linejoin: round;
    /* every path carries pathLength="100", so one dash length fits all */
    stroke-dasharray: 100;
    stroke-dashoffset: 100;
    animation: edp-doodle-draw 1500ms cubic-bezier(0.33, 0, 0.2, 1) both;
}

.edp-doodle-line--faint {
    stroke-width: 1.1;
    opacity: 0.55;
}

.edp-doodle-line--1  { animation-delay: 120ms; }
.edp-doodle-line--2  { animation-delay: 320ms; }
.edp-doodle-line--3  { animation-delay: 520ms; }
.edp-doodle-line--4  { animation-delay: 660ms; }
.edp-doodle-line--5  { animation-delay: 780ms; }
.edp-doodle-line--6  { animation-delay: 900ms; }
.edp-doodle-line--7  { animation-delay: 1020ms; }
.edp-doodle-line--8  { animation-delay: 1140ms; }
.edp-doodle-line--9  { animation-delay: 1260ms; }
.edp-doodle-line--10 { animation-delay: 1340ms; }

.edp-doodle-leaf {
    fill: var(--edp-accent-soft);
    stroke: var(--edp-accent);
    stroke-width: 1.4;
    stroke-linecap: round;
    stroke-linejoin: round;
    stroke-dasharray: 100;
    stroke-dashoffset: 100;
    animation: edp-doodle-draw 1500ms cubic-bezier(0.33, 0, 0.2, 1) both,
               edp-doodle-fade 900ms ease 700ms both;
}

.edp-doodle-dot {
    fill: var(--edp-accent);
    opacity: 0.55;
}

.edp-doodle-dot--sm {
    opacity: 0.4;
}

.edp-doodle-ring {
    fill: none;
    stroke: var(--edp-accent);
    stroke-width: 1.4;
    opacity: 0.5;
}

/* The sprig and the accent clusters do ONE settle pass that starts as the
   draw-on finishes and ends on `transform: none` — the resting state. They
   are then completely static until the hero is hovered. */
.edp-doodle-sprig,
.edp-doodle-float {
    transform-box: fill-box;
    transform-origin: center;
}

.edp-doodle-sprig {
    animation: edp-doodle-settle-sway 2600ms cubic-bezier(0.22, 0.61, 0.36, 1) 1100ms both;
}

.edp-doodle-float--a {
    animation: edp-doodle-settle-a 2400ms cubic-bezier(0.22, 0.61, 0.36, 1) 1200ms both;
}

.edp-doodle-float--b {
    animation: edp-doodle-settle-b 2400ms cubic-bezier(0.22, 0.61, 0.36, 1) 1350ms both;
}

.edp-doodle-float--c {
    animation: edp-doodle-settle-c 2400ms cubic-bezier(0.22, 0.61, 0.36, 1) 1500ms both;
}

/* Ambient sway/drift resumes on hover only. */
.edp-hero:hover .edp-doodle-sprig {
    animation: edp-doodle-sway 17s ease-in-out infinite alternate;
}

.edp-hero:hover .edp-doodle-float--a {
    animation: edp-doodle-drift-a 21s ease-in-out infinite alternate;
}

.edp-hero:hover .edp-doodle-float--b {
    animation: edp-doodle-drift-b 26s ease-in-out infinite alternate;
}

.edp-hero:hover .edp-doodle-float--c {
    animation: edp-doodle-drift-c 19s ease-in-out infinite alternate;
}

@keyframes edp-doodle-draw {
    from { stroke-dashoffset: 100; }
    to   { stroke-dashoffset: 0; }
}

@keyframes edp-doodle-fade {
    from { fill-opacity: 0; }
    to   { fill-opacity: 1; }
}

/* One-shot settles — all end on the static resting frame. */
@keyframes edp-doodle-settle-sway {
    0%   { transform: translate3d(0, -6px, 0) rotate(1.6deg); }
    60%  { transform: translate3d(0, 2px, 0) rotate(-0.5deg); }
    100% { transform: none; }
}

@keyframes edp-doodle-settle-a {
    0%   { transform: translate3d(-10px, 8px, 0); }
    100% { transform: none; }
}

@keyframes edp-doodle-settle-b {
    0%   { transform: translate3d(8px, -7px, 0); }
    100% { transform: none; }
}

@keyframes edp-doodle-settle-c {
    0%   { transform: translate3d(-5px, -5px, 0) rotate(2deg); }
    100% { transform: none; }
}

/* Hover-only ambient loops. */
@keyframes edp-doodle-sway {
    0%   { transform: translate3d(0, 0, 0) rotate(0deg); }
    50%  { transform: translate3d(2px, -6px, 0) rotate(1.6deg); }
    100% { transform: translate3d(-2px, 3px, 0) rotate(-1.2deg); }
}

@keyframes edp-doodle-drift-a {
    0%   { transform: translate3d(0, 0, 0); }
    100% { transform: translate3d(-10px, 8px, 0); }
}

@keyframes edp-doodle-drift-b {
    0%   { transform: translate3d(0, 0, 0); }
    100% { transform: translate3d(8px, -7px, 0); }
}

@keyframes edp-doodle-drift-c {
    0%   { transform: translate3d(0, 0, 0) rotate(0deg); }
    100% { transform: translate3d(-5px, -5px, 0) rotate(2deg); }
}

.edp-hero-inner {
    position: relative;
    z-index: 1;
}

/* ---------------- COPY ------------------------------------------------ */
.edp-hero-copy {
    padding-right: $sp-space-6;
}

.edp-hero-eyebrow {
    display: inline-flex;
    align-items: center;
    gap: $sp-space-2;
    margin: 0 0 $sp-space-4;
    padding: $sp-space-1 $sp-space-3;
    border-radius: var(--edp-radius-pill);
    background-color: var(--edp-surface-strong);
    border: 1px solid var(--edp-hairline);
    color: var(--edp-text-secondary);
    font-size: $sp-text-xs;
    font-weight: 700;
    letter-spacing: 0.12em;
    text-transform: uppercase;
}

.edp-hero-eyebrow-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background-color: var(--edp-accent);
    display: inline-block;
}

.edp-hero-headline {
    color: var(--edp-text);
    font-size: $sp-text-2xl;
    font-weight: 700;
    line-height: 1.15;
    letter-spacing: -0.015em;
    margin: 0 0 $sp-space-4;
    max-width: 22ch;
}

.edp-hero-sub {
    color: var(--edp-text-secondary);
    font-size: $sp-text-md;
    line-height: 1.6;
    margin: 0 0 $sp-space-6;
    max-width: 46ch;
}

.edp-hero-actions {
    display: flex;
    flex-wrap: wrap;
    gap: $sp-space-3;
}

.edp-hero-cta {
    padding: $sp-space-3 $sp-space-5;
    font-size: $sp-text-base;
    box-shadow: var(--edp-shadow-1);
    transition: transform 180ms cubic-bezier(0.2, 0.8, 0.2, 1),
                box-shadow 180ms ease,
                background-color 180ms ease;
}

.edp-hero-cta:hover,
.edp-hero-cta:focus {
    transform: translateY(-2px);
    box-shadow: var(--edp-shadow-2);
}

.edp-hero-cta-icon {
    margin-left: $sp-space-2;
    font-size: $sp-icon-xs;
    transition: transform 180ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.edp-hero-cta:hover .edp-hero-cta-icon {
    transform: translateX(3px);
}

.edp-hero-actions .btn-default {
    padding: $sp-space-3 $sp-space-5;
    font-size: $sp-text-base;
}

/* ---------------- CAROUSEL -------------------------------------------- */
/* Frosted pane: heavy blur + saturation over the hero background, a
 * near-opaque glass surface so the slide copy keeps 4.5:1 in both themes,
 * a diagonal specular sheen, a sage bloom for depth and a crisp inner edge. */
.edp-carousel {
    position: relative;
    overflow: hidden;
    isolation: isolate;
    border-radius: var(--edp-radius-lg);
    background-color: var(--edp-glass-surface);
    border: 1px solid var(--edp-hairline);
    box-shadow:
        var(--edp-shadow-3),
        inset 0 1px 0 var(--edp-glass-highlight),
        inset 0 0 0 1px var(--edp-glass-edge);
    -webkit-backdrop-filter: blur(var(--edp-blur-glass)) saturate(var(--edp-glass-saturate));
    backdrop-filter: blur(var(--edp-blur-glass)) saturate(var(--edp-glass-saturate));
    padding: $sp-space-5;
    min-height: 300px;
    display: flex;
    flex-direction: column;
}

@supports not ((-webkit-backdrop-filter: blur(1px)) or (backdrop-filter: blur(1px))) {
    .edp-carousel {
        background-color: var(--edp-surface-strong);
    }
}

.edp-carousel-sheen {
    position: absolute;
    inset: 0;
    z-index: 0;
    display: block;
    pointer-events: none;
    background-image: linear-gradient(
        158deg,
        var(--edp-glass-sheen) 0%,
        var(--edp-glass-sheen-soft) 30%,
        transparent 56%
    );
}

.edp-carousel-bloom {
    position: absolute;
    top: -34%;
    right: -20%;
    width: 72%;
    padding-bottom: 72%;
    z-index: 0;
    display: block;
    border-radius: 50%;
    background: var(--edp-aurora-1);
    filter: blur(58px);
    opacity: 0.55;
    pointer-events: none;
}

.edp-carousel-bar,
.edp-carousel-viewport,
.edp-carousel-dots {
    position: relative;
    z-index: 1;
}

.edp-carousel-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: $sp-space-5;
}

.edp-carousel-counter {
    padding: $sp-space-1 $sp-space-3;
    border-radius: var(--edp-radius-pill);
    border: 1px solid var(--edp-hairline);
    background-color: var(--edp-surface-sunken);
    color: var(--edp-text-secondary);
    font-size: $sp-text-xs;
    font-weight: 700;
    letter-spacing: 0.08em;
}

.edp-carousel-buttons {
    display: flex;
    gap: $sp-space-2;
}

/* Only the play/pause control remains in the bar — the prev/next arrows were
   removed. Slide selection lives on the dots and on the arrow keys. */
.edp-carousel-btn {
    width: 36px;
    height: 36px;
    padding: 0;
    border-radius: 50%;
    border: 1px solid var(--edp-hairline-strong);
    background-color: var(--edp-surface-strong);
    color: var(--edp-accent-ink);
    font-size: $sp-icon-xs;
    line-height: 1;
    box-shadow: inset 0 1px 0 var(--edp-glass-highlight);
    transition: background-color 180ms ease,
                border-color 180ms ease,
                box-shadow 180ms ease,
                transform 180ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.edp-carousel-btn:hover {
    background-color: var(--edp-accent-soft-hover);
    border-color: var(--edp-accent);
    box-shadow: var(--edp-shadow-1), inset 0 1px 0 var(--edp-glass-highlight);
    transform: translateY(-1px);
}

.edp-carousel-btn--play {
    border-color: var(--edp-accent);
}

/* ---------------- SLIDE TRACK -----------------------------------------
 * EVERY slide stays mounted and they all share ONE grid cell, so:
 *   * the track height is the height of the TALLEST slide and never
 *     collapses or jumps when the active slide changes;
 *   * swapping slides is a class change, not a DOM insert/remove, so
 *     ngAnimate never keeps an outgoing node alive next to the incoming one
 *     (that overlap was the "two slides visible at once" bug);
 *   * exactly one slide is painted: the inactive ones are
 *     `visibility: hidden` (which also drops their links out of the tab
 *     order) and get no leave animation, so they disappear in the same frame
 *     the incoming slide starts drawing.
 * -------------------------------------------------------------------- */
.edp-carousel-viewport {
    flex: 1 1 auto;
    display: grid;
    grid-template-areas: 'edp-slide';
    overflow: hidden;
}

.edp-carousel-slide {
    grid-area: edp-slide;
    min-width: 0;
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
}

/* Fallback for engines without CSS grid: stack absolutely and reserve height. */
@supports not (display: grid) {
    .edp-carousel-viewport {
        position: relative;
        min-height: 220px;
    }

    .edp-carousel-slide {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
    }
}

.edp-carousel-slide.is-active {
    opacity: 1;
    visibility: visible;
    pointer-events: auto;
    /* Re-applied every time the class lands on a new node, so the incoming
       slide always animates in. The outgoing slide has no animation at all. */
    animation: edp-slide-in-next 420ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

/* Directional entrance: the controller puts `is-prev` / `is-next` on the
   viewport, so the new slide enters from the side the user travelled towards. */
.edp-carousel-viewport.is-prev .edp-carousel-slide.is-active {
    animation-name: edp-slide-in-prev;
}

@keyframes edp-slide-in-next {
    from { opacity: 0; transform: translate3d(22px, 6px, 0) scale(0.985); }
    to   { opacity: 1; transform: translate3d(0, 0, 0) scale(1); }
}

@keyframes edp-slide-in-prev {
    from { opacity: 0; transform: translate3d(-22px, 6px, 0) scale(0.985); }
    to   { opacity: 1; transform: translate3d(0, 0, 0) scale(1); }
}

.edp-carousel-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 56px;
    height: 56px;
    border-radius: var(--edp-radius);
    background-image: linear-gradient(
        145deg,
        var(--edp-accent-soft-hover) 0%,
        var(--edp-accent-soft) 100%
    );
    border: 1px solid var(--edp-accent);
    box-shadow: inset 0 1px 0 var(--edp-glass-highlight);
    color: var(--edp-accent-ink);
    font-size: $sp-icon-md;
    margin-bottom: $sp-space-4;
}

.edp-carousel-title {
    color: var(--edp-text);
    font-size: $sp-text-lg;
    font-weight: 700;
    line-height: 1.25;
    letter-spacing: -0.01em;
    margin: 0 0 $sp-space-3;
}

.edp-carousel-text {
    color: var(--edp-text-secondary);
    font-size: $sp-text-base;
    line-height: 1.6;
    margin: 0 0 $sp-space-5;
    max-width: 44ch;
}

.edp-carousel-link {
    display: inline-flex;
    align-items: center;
    gap: $sp-space-2;
    padding: $sp-space-2 $sp-space-4;
    border-radius: var(--edp-radius-pill);
    border: 1px solid var(--edp-hairline-strong);
    background-color: var(--edp-accent-soft);
    color: var(--edp-accent-ink);
    font-size: $sp-text-sm;
    font-weight: 700;
    text-decoration: none;
    transition: background-color 180ms ease,
                border-color 180ms ease,
                transform 180ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.edp-carousel-link:hover,
.edp-carousel-link:focus {
    background-color: var(--edp-accent-soft-hover);
    border-color: var(--edp-accent);
    color: var(--edp-accent-ink);
    text-decoration: none;
    transform: translateY(-1px);
}

.edp-carousel-link-icon {
    font-size: $sp-icon-sm;
    transition: transform 180ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.edp-carousel-link:hover .edp-carousel-link-icon,
.edp-carousel-link:focus .edp-carousel-link-icon {
    transform: translateX(3px);
}

/* --- indicators: a track that fills for the current slide --- */
.edp-carousel-dots {
    display: flex;
    align-items: center;
    gap: $sp-space-2;
    margin-top: $sp-space-5;
    padding-top: $sp-space-4;
    border-top: 1px solid var(--edp-hairline);
}

.edp-carousel-dot {
    position: relative;
    width: 28px;
    height: 8px;
    padding: 0;
    border: 0;
    overflow: hidden;
    border-radius: var(--edp-radius-pill);
    background-color: var(--edp-hairline-strong);
    transition: width 280ms cubic-bezier(0.2, 0.8, 0.2, 1),
                background-color 200ms ease;
}

.edp-carousel-dot-fill {
    position: absolute;
    inset: 0;
    display: block;
    border-radius: inherit;
    background-image: linear-gradient(
        90deg,
        var(--edp-accent) 0%,
        var(--edp-accent-hover) 100%
    );
    transform: scaleX(0);
    transform-origin: left center;
    transition: transform 320ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.edp-carousel-dot:hover {
    background-color: var(--edp-accent-soft-hover);
}

.edp-carousel-dot:hover .edp-carousel-dot-fill {
    transform: scaleX(0.45);
}

.edp-carousel-dot.is-active {
    width: 46px;
    background-color: var(--edp-accent-soft-hover);
}

.edp-carousel-dot.is-active .edp-carousel-dot-fill {
    transform: scaleX(1);
}

/* ---------------- RESPONSIVE ----------------------------------------- */
@media (max-width: 991px) {
    .edp-hero {
        padding: $sp-space-6 $sp-space-5;
    }

    .edp-hero-copy {
        padding-right: 0;
        margin-bottom: $sp-space-6;
    }

    .edp-hero-headline {
        font-size: $sp-text-xl;
        max-width: none;
    }

    .edp-hero-sub {
        max-width: none;
    }

    .edp-doodle-svg {
        width: 58%;
        opacity: 0.45;
    }
}

@media (max-width: 767px) {
    .edp-hero {
        padding: $sp-space-5 $sp-space-4;
        border-radius: var(--edp-radius);
    }

    .edp-hero-actions .btn {
        width: 100%;
        text-align: center;
    }

    .edp-carousel {
        padding: $sp-space-4;
        min-height: 0;
    }

    /* Purely decorative — dropped on the smallest viewports to keep the hero
       copy uncluttered. */
    .edp-doodle {
        display: none;
    }
}

/* ---------------- REDUCED MOTION (MANDATORY) -------------------------
 * Kills BOTH the one-shot settle animations and the hover-only ambient
 * loops, and renders the doodle in its final drawn state.
 * ------------------------------------------------------------------- */
@media (prefers-reduced-motion: reduce) {
    .edp-hero-blob--1,
    .edp-hero-blob--2,
    .edp-hero-blob--3,
    .edp-hero:hover .edp-hero-blob--1,
    .edp-hero:hover .edp-hero-blob--2,
    .edp-hero:hover .edp-hero-blob--3 {
        animation: none;
        transform: none;
    }

    /* Doodle: NO animation at all, rendered in its final drawn state. */
    .edp-doodle-line,
    .edp-doodle-leaf {
        animation: none;
        stroke-dashoffset: 0;
    }

    .edp-doodle-leaf {
        fill-opacity: 1;
    }

    .edp-doodle-sprig,
    .edp-doodle-float,
    .edp-doodle-float--a,
    .edp-doodle-float--b,
    .edp-doodle-float--c,
    .edp-hero:hover .edp-doodle-sprig,
    .edp-hero:hover .edp-doodle-float--a,
    .edp-hero:hover .edp-doodle-float--b,
    .edp-hero:hover .edp-doodle-float--c {
        animation: none;
        transform: none;
    }

    /* Slides swap instantly; still exactly one visible. */
    .edp-carousel-slide.is-active,
    .edp-carousel-viewport.is-prev .edp-carousel-slide.is-active {
        animation: none;
    }

    .edp-hero-cta,
    .edp-hero-cta-icon,
    .edp-carousel-btn,
    .edp-carousel-dot,
    .edp-carousel-dot-fill,
    .edp-carousel-link,
    .edp-carousel-link-icon {
        transition: none;
    }

    .edp-hero-cta:hover,
    .edp-hero-cta:focus {
        transform: none;
    }

    .edp-hero-cta:hover .edp-hero-cta-icon {
        transform: none;
    }

    .edp-carousel-btn:hover,
    .edp-carousel-link:hover,
    .edp-carousel-link:focus {
        transform: none;
    }

    .edp-carousel-link:hover .edp-carousel-link-icon,
    .edp-carousel-link:focus .edp-carousel-link-icon {
        transform: none;
    }
}

sp_widget.script:
/* ==========================================================================
 * EDP Hero + Carousel — server script
 * ==========================================================================
 * Widget server scripts DO use the IIFE pattern (unlike headers/footers).
 * Scoped app: gs.info / gs.error only, new GlideDateTime(), explicit
 * GlideRecord. No gs.print, no nowDateTime(), no implicit `current`.
 *
 * Every `data.*` property is initialised up front so the template can never
 * bind to undefined.
 * ========================================================================== */
(function () {

    /* ---- defaults ------------------------------------------------------ */
    data.eyebrow = '';
    data.headline = '';
    data.subheadline = '';
    data.primaryCtaLabel = '';
    data.primaryCtaUrl = '';
    data.secondaryCtaLabel = '';
    data.secondaryCtaUrl = '';
    data.carouselLabel = '';
    data.slides = [];
    data.autoplay = true;
    data.intervalMs = 7000;
    data.showDoodle = true;

    /* ---- translated strings for the client ----------------------------- */
    data.msg = {
        previous: gs.getMessage('Previous slide'),
        next: gs.getMessage('Next slide'),
        play: gs.getMessage('Start automatic slide rotation'),
        pause: gs.getMessage('Pause automatic slide rotation'),
        chooseSlide: gs.getMessage('Choose a slide to display')
    };

    /* ---- options ------------------------------------------------------- */
    data.eyebrow = options.eyebrow || gs.getMessage('Enterprise Digital');
    data.headline = options.headline || gs.getMessage('Change, governed end to end.');
    data.subheadline = options.subheadline || gs.getMessage(
        'Raise a review, schedule a deployment and follow every request through to ' +
        'completion — from one place.');
    data.primaryCtaLabel = options.primary_cta_label || gs.getMessage('Browse the catalog');
    data.primaryCtaUrl = options.primary_cta_url || '?id=sc_landing';
    data.secondaryCtaLabel = options.secondary_cta_label || gs.getMessage('My requests');
    data.secondaryCtaUrl = options.secondary_cta_url || '?id=requests';
    data.carouselLabel = options.carousel_label || gs.getMessage('Featured Enterprise Digital services');

    // Booleans arrive as the strings 'true' / 'false' when they come from
    // widgetParameters — compare against both forms.
    data.autoplay = options.autoplay !== false && options.autoplay !== 'false';

    // Decorative animated SVG doodle in the hero. Switchable from the Service
    // Portal Designer with no code change; it never affects behaviour or AT
    // output because the markup is aria-hidden and pointer-events: none.
    data.showDoodle = options.show_doodle !== false && options.show_doodle !== 'false';

    var parsedInterval = parseInt(options.interval_ms, 10);
    data.intervalMs = (!isNaN(parsedInterval) && parsedInterval >= 3000) ? parsedInterval : 7000;

    /* ---- slides -------------------------------------------------------- *
     * `slides_json` is a JSON array of:
     *   { "title": "...", "text": "...", "icon": "<font-awesome name,
     *     without the fa- prefix>", "ctaLabel": "...", "ctaUrl": "?id=..." }
     * Edit it from the Service Portal Designer — no code change needed.
     * ------------------------------------------------------------------- */
    var FALLBACK_SLIDES = [
        {
            title: gs.getMessage('Change Review Board'),
            text: gs.getMessage('Put a change in front of the board, capture the risk rating and track the decision.'),
            icon: 'check-square-o',
            ctaLabel: gs.getMessage('Request a review'),
            ctaUrl: '?id=sc_cat_item&sys_id=7518ecedb14542a59ccfc62d5058a8d5'
        },
        {
            title: gs.getMessage('Change Deployment'),
            text: gs.getMessage('Book a deployment window, record the rollback plan and verify the outcome.'),
            icon: 'rocket',
            ctaLabel: gs.getMessage('Schedule a deployment'),
            ctaUrl: '?id=sc_cat_item&sys_id=9639f638440e4833b8b56ec59845cec4'
        },
        {
            title: gs.getMessage('One governed catalog'),
            text: gs.getMessage('Every Enterprise Digital delivery service, in a single catalog you can search.'),
            icon: 'th-large',
            ctaLabel: gs.getMessage('Open the catalog'),
            ctaUrl: '?id=sc_landing'
        }
    ];

    data.slides = FALLBACK_SLIDES;

    if (options.slides_json && (options.slides_json + '').trim() !== '') {
        try {
            var parsed = JSON.parse(options.slides_json + '');
            if (parsed && parsed.length) {
                var cleaned = [];
                for (var i = 0; i < parsed.length; i++) {
                    var raw = parsed[i] || {};
                    if (!raw.title) {
                        continue;
                    }
                    cleaned.push({
                        title: raw.title + '',
                        text: raw.text ? raw.text + '' : '',
                        icon: raw.icon ? raw.icon + '' : 'circle-o',
                        ctaLabel: raw.ctaLabel ? raw.ctaLabel + '' : '',
                        ctaUrl: raw.ctaUrl ? raw.ctaUrl + '' : ''
                    });
                }
                if (cleaned.length) {
                    data.slides = cleaned;
                }
            }
        } catch (parseErr) {
            gs.error('[EDP hero] slides_json is not valid JSON, falling back to defaults: ' + parseErr);
        }
    }
})();
